-- GenDB engine variant Q17-commuted_comparisons: template q17.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice) / 7.0 AS avg_yearly
FROM lineitem, part
WHERE
  l_partkey = p_partkey
  AND $1 = p_brand
  AND $2 = p_container
  AND (
    SELECT
      0.2 * AVG(l_quantity)
    FROM lineitem
    WHERE
      p_partkey = l_partkey
  ) > l_quantity
